CREATE TABLE one_badge (id INT PRIMARY KEY, label VARCHAR(24) NOT NULL);
INSERT INTO one_badge (label, id) VALUES ('新手', 12);
SELECT id, label FROM one_badge WHERE id = 12;

CREATE TABLE candidate_badges (id INT PRIMARY KEY, label VARCHAR(24), enabled INT);
CREATE TABLE chosen_badges (id INT PRIMARY KEY, label VARCHAR(24));
INSERT INTO candidate_badges VALUES (1,'晨读',1),(2,'夜读',0);
INSERT INTO chosen_badges (id, label)
 SELECT id, label FROM candidate_badges WHERE enabled = 1;

CREATE TABLE replace_demo (id INT PRIMARY KEY, label VARCHAR(24), remark VARCHAR(24) DEFAULT '未备注');
INSERT INTO replace_demo VALUES (1,'旧标签','人工备注');
REPLACE INTO replace_demo (id, label) VALUES (1,'新标签');

CREATE TABLE clear_demo (id INT PRIMARY KEY, label VARCHAR(20));
INSERT INTO clear_demo VALUES (1,'临时'),(2,'待清');
TRUNCATE TABLE clear_demo;
SELECT id, label FROM clear_demo;

CREATE TABLE score_practice (id INT PRIMARY KEY, score INT);
INSERT INTO score_practice VALUES (1,55),(2,70),(3,NULL);
UPDATE score_practice SET score = score + 5 WHERE score IS NOT NULL;
DELETE FROM score_practice WHERE score < 60 OR score IS NULL;
SELECT id, score FROM score_practice ORDER BY id;
